select Grower {
  slug,
  name,
  region: {
    code,
    name
  },
  batches := (
    select .<grower[is Batch] {
      code,
      kilograms,
      harvested_on,
      certifications
    }
    filter (
      ((.kilograms >= <optional float64>$min_kilograms) ?? true) and
      ((not exists array_unpack(<array<str>>$certifications)) or any(array_unpack(<array<str>>$certifications) in .certifications))
    )
    order by .code asc
  )
}
filter .region.code = <str>$region_code
order by .slug asc;

select Batch {
  code,
  kilograms,
  harvested_on,
  certifications,
  grower: {
    slug,
    name,
    region: {
      code,
      name
    }
  },
  inspection_count := count(.<batch[is Inspection])
}
filter .code = <str>$code;

select (
  insert Inspection {
    batch := (select Batch filter .code = <str>$batch_code limit 1),
    inspector := <str>$inspector,
    passed := <bool>$passed,
    defects := (
      for x in array_unpack(<array<str>>$defect_codes)
      union (
        insert Defect {
          code := x,
          severity := <int64>$severity
        }
      )
    )
  }
) {
  id,
  inspector,
  passed,
  defect_count := count(.defects),
  batch_code := .batch.code
};

select Region {
  code,
  name,
  grower_count := count(.<region[is Grower]),
  batch_count := count(.<region[is Grower].<grower[is Batch]),
  total_kilograms := sum(.<region[is Grower].<grower[is Batch].kilograms)
}
filter (
  (not exists array_unpack(<array<str>>$region_codes)) or
  (.code in array_unpack(<array<str>>$region_codes))
)
order by .code asc;

