async def list_region_growers(
    executor: gel.AsyncIOExecutor,
    *,
    min_kilograms: float | None = None,
    certifications: list[str],
    region_code: str,
) -> list[ListRegionGrowersResult]:
    return await executor.query(
        """\
        select Grower {
          slug,
          name,
          region: {
            code,
            name
          },
          batches := (
            select .<grower[is Batch] {
              code,
